#include <iostream>
#include <vector>
using namespace std;
using int64 = long long;

// 判断 n 的十进制位数是否等于 d
bool check(int64 n, int d, const vector<int64>& p10) {
    return p10[d-1] <= n && n < p10[d];
}

int64 solve(int64 S, const vector<int64>& p10) {
    // 枚举可能的位数 d
    for (int d = 1; d <= 18; ++d) {
        if (S % d != 0) continue;
        int64 N = S / d;
        if (N >= 1 && N <= 1000000000000000000LL && check(N, d, p10)) {
            return N;
        }
    }
    return -1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    // 预处理 10 的幂
    vector<int64> p10(19);
    p10[0] = 1;
    for (int i = 1; i <= 18; ++i) {
        p10[i] = p10[i-1] * 10;
    }

    while (T--) {
        int64 S;
        cin >> S;
        cout << solve(S, p10) << '\n';
    }

    return 0;
}
